import {CAnalysis, analyzeTsCode} from 'typescript'

// --- These may become command line options later
const oneIndent = '\n'
const maxLineLen = 75

stdChecks("build-dot-symbols")

// ---------------------------------------------------------------------------
// --- TIterator

const allLinesFrom = function*(
		lExports: string[]
		): TIterator<string> {

	const lSymbols: string[] = []
	let lineLen = 0     // --- always <= maxLineLen
	for (const name of lExports) {
		const pos = name.indexOf('<')
		const sym = (pos === -1) ? name : name.substring(0, pos)
		if (lineLen + sym.length + 1 > maxLineLen) {
			yield lSymbols.join(' ')
			lSymbols.length = 0
			lineLen = 0
		}
		else {
			lSymbols.push(sym)
			lineLen += sym.length + 1
		}
	}
	if (lSymbols.length > 0) {
		yield lSymbols.join(' ')
	}
	return
}

// ---------------------------------------------------------------------------

EXEC(async () => {

	using file = await openForWrite('src/.symbols')

	for (const path of allFilesMatching('**/*.lib.ts')) {
		try {
			const analysis = analyzeTsCode(Deno.readTextFileSync(path))
			const lExports = analysis.getExports()
			LOG(`${toRelPath(path)} - ${lExports.length} exports`)
			const {stub} = parsePath(path)

			await writeLine(file, stub)
			for (const line of allLinesFrom(lExports)) {
				await writeLine(file, indented(line))
			}
		}
//				await file.write encode(indented(line + '\n'))
		catch (err) {
			ERR(err)
		}
	}
})

